#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    size_t count = 4;
    int *scores = calloc(count, sizeof *scores);
    if (scores == NULL) {
        return 1;
    }
    scores[2] = 9;
    printf("%d %d %d\n", scores[0], scores[2], scores[3]);
    free(scores);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

int main(void)
{
    size_t count = 5;
    int *values = NULL;
    if (count > SIZE_MAX / sizeof *values) {
        return 1;
    }
    values = malloc(count * sizeof *values);
    if (values == NULL) {
        return 1;
    }
    for (size_t i = 0; i < count; i++) {
        values[i] = (int)i + 1;
    }
    printf("Last: %d\n", values[count - 1]);
    free(values);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    unsigned int *counts = calloc(3, sizeof *counts);
    if (counts == NULL) {
        return 1;
    }
    int groups[] = {1, 0, 1, 2, 1};
    for (size_t i = 0; i < sizeof groups / sizeof groups[0]; i++) {
        counts[groups[i]]++;
    }
    printf("%u %u %u\n", counts[0], counts[1], counts[2]);
    free(counts);
    return 0;
}

